
import { useEffect, useState } from "react";
import { useForm, useWatch } from "react-hook-form";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { toast } from "sonner";
import { initMercadoPago } from '@mercadopago/sdk-react';


import { useUsuarioStore } from "../../store/Usuario";
import { useValidarSesion } from "../../hooks/useValidarSesion";

// COMPONENTES
import Pestanias from "../../Componentes/Pestanias/Pestanias";
import PlantillaPages from '../../Componentes/PlantillaPages/PlantillaPages'
import Boton from '../../Componentes/Boton/Boton'
import PanelVender from '../../Componentes/Paneles/PanelVender/PanelVender'
import AgregarProductoCarrito from "../../Componentes/Formularios/AgregarProductoCarrito/AgregarProductoCarrito";
import Modal from "../../Componentes/Modal/Modal";
import TablaConPaginacion from "../../Componentes/TablaConPaginacion/TablaConPaginacion";
import Tarjeta from "../../Componentes/ComponentesFormulario/Tarjeta/Tarjeta";
import Input from "../../Componentes/Input/Input";

// ESTILOS
import './Vender.css'
import columnas from "../../Datos_Pruebas/Columnas_Vender.json"
import agregar_carrito from '../../assets/agregar_carrito.png'
import quitar_carrito from '../../assets/quitar_carrito.png'

// ------------------------------
// VARIABLES DE ENTORNO
// ------------------------------
const API_URL = import.meta.env.VITE_API_URL;
const MP_PUBLIC_KEY = import.meta.env.VITE_MP_PUBLIC_KEY;



export default function Vender() {

  // Inicialización de MercadoPago
  initMercadoPago(MP_PUBLIC_KEY, { locale: "es-AR" }); // con clave publica del vendedor

  const { storeCargado, token, usuario } = useValidarSesion();


  //BOOLEANO PARA PREGUNTAR SI EL USUARIO TIENE PERMISO DE agregar un decuento general
  const permisoAgregarDescGeneral =
    usuario?.permisos?.some(
      (permiso) => permiso.nombrePermiso === 'descuento gral'
    ) ||
    usuario?.permisos_extra?.some(
      (permiso) => permiso.nombrePermiso === 'descuento gral'
    );


  const esSuperAdmin = usuario?.rol?.[0]?.nombreRol === "superadmin";

  const [productos, setProductos] = useState([]);
  const [ventaPendiente, setVentaPendiente] = useState(null);
  const [modalAgregarProducto, setModalAgregarProducto] = useState(false);
  const [seleccionado, setSeleccionado] = useState(null);
  const [cargando, setCargando] = useState(false);


  const [idSucursalSeleccionada, setIdSucursalSeleccionada] = useState(
    esSuperAdmin ? null : usuario?.sucursal?.[0]?.id_sucursal || null
  );


  // FORMULARIO hookk form

  const { register, handleSubmit, formState: { errors }, control, setValue, reset } = useForm({
    defaultValues: {
      descuento_gral: 0,
      metodo_pago: "Efectivo"
    }
  });

  const datosFormulario = useWatch({ control });



  // CALCULO DE TOTALES

  useEffect(() => {
    const descuento = datosFormulario.descuento_gral / 100;

    const totalNeto = productos.reduce((acc, producto) => {
      const neto = parseFloat(producto.Neto?.replace('$', '').replace(',', '.'));
      return !isNaN(neto) ? acc + neto : acc;
    }, 0);

    const totalConDescuento = totalNeto * (1 - descuento);

    setValue("total", totalNeto.toFixed(2).replace('.', ','));
    setValue("total_con_descuento", totalConDescuento.toFixed(2).replace('.', ','));
  }, [productos, datosFormulario.descuento_gral, setValue]);



  // CREAR PREFERENCIA MERCADOPAGO

  const createPreference = async (datosVenta) => {
    setCargando(true);
    console.log('datosVenta en createPreference:', datosVenta);
    try {
      const respuesta = await axios.post(`${API_URL}/api/pagos/crear-preferencia`, { //se manda la preferencia de pago
        title: `Venta de  ${usuario?.nombre}, ${usuario?.apellido}`,                      //si es aceptada se manda un el id_preferencia
        quantity: 1,
        price: parseFloat(datosVenta.total_con_descuento),
        datos_venta: datosVenta,
      });

      return respuesta.data.init_point; // <--- init_point para abrir directo sin Wallet UI
    } catch (error) {
      toast.error("Error al crear la preferencia de pago", { className: "__toaster_error" });
      return null;
    } finally {
      setCargando(false);
    }
  };


  // VALIDAR STOCK + GENERAR PREFERENCIA

  const handleBuy = async (datosVenta) => {


    try {
      const respuestaValidacion = await fetch(
  `${import.meta.env.VITE_API_BASE_URL}/api/venta/validar-stock`,
        {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'Authorization': `Bearer ${token}`
          },
          body: JSON.stringify({
            productos: datosVenta.productos,
            id_sucursal: datosVenta.id_sucursal
          }),
        }
      );

      const validacionData = await respuestaValidacion.json();

      if (!respuestaValidacion.ok) {
        toast.error(validacionData.detalle || validacionData.error || 'Error al validar stock');
        return;
      }

      // Si pasa entocnes recien se crea la  preferencia
      const initPoint = await createPreference(datosVenta);


      if (initPoint) {
        window.open(initPoint, "_blank");
        reset();
        setProductos([]);
      }

    } catch (error) {
      toast.error("Error inesperado al validar stock");
    }
  };



  // AGREGAR PRODUCTO AL CARRITO

  const manejarAgregarProducto = async (item) => {
    try {
      let url = item.esCombo
  ? `${import.meta.env.VITE_API_BASE_URL}/api/combo/${item.id_combo}`
  : `${import.meta.env.VITE_API_BASE_URL}/api/producto/${item.id_producto}/mostrar2`;

      const respuesta = await fetch(url, {
        method: item.esCombo ? "GET" : "POST",
        headers: {
          "Content-Type": "application/json",
          "Authorization": `Bearer ${token}`
        },
        body: item.esCombo ? null : JSON.stringify({ id_sucursal: idSucursalSeleccionada })
      });

      const datos = await respuesta.json();
      const final = { ...item, ...datos };

      const datosTransformados = item.esCombo
        ? {
          esCombo: true,
          id_combo: final.id_combo,
          Codigo: final.codigo,
          Nombre: final.nombre,
          Cantidad: final.cantidad,
          Subtotal: `$ ${(parseFloat(final.costo.replace(',', '.')) * final.cantidad).toFixed(2).replace('.', ',')}`,
          IVA: 0,
          Descuento: 0,
          Neto: `$ ${(parseFloat(final.costo.replace(',', '.')) * final.cantidad).toFixed(2).replace('.', ',')}`
        }
        : {
          esCombo: false,
          id_producto: final.id_producto,
          Codigo: final.codigo,
          Nombre: final.Nombre,
          Cantidad: final.cantidad,
          Subtotal: `$ ${(parseFloat(final.costo.replace(',', '.')) * final.cantidad).toFixed(2).replace('.', ',')}`,
          IVA: final.IVA,
          Descuento: `${final.descuento === null ? "0" : final.descuento.porcentaje} %`,
          Neto: `$ ${(
            parseFloat(final.costo.replace(',', '.')) *
            (1 + final.IVA / 100) *
            (1 - (final.descuento === null ? 0 : final.descuento.porcentaje / 100)) *
            final.cantidad
          ).toFixed(2).replace('.', ',')}`
        };

      setProductos([...productos, datosTransformados]);
    } catch (error) {
      console.error("Error:", error);
    }
  };



  // QUITAR PRODUCTO

  const quitarProducto = () => {
    if (!seleccionado) return;

    setProductos(productos.filter(p =>
      seleccionado.esCombo
        ? p.id_combo !== seleccionado.id_combo
        : p.id_producto !== seleccionado.id_producto
    ));

    setSeleccionado(null);
  };



  // SUBMIT FORM

  const onSubmit = async (data) => {

    if (data.metodo_pago === "Tarjeta Debito" || data.metodo_pago === "Tarjeta Credito") {
      if (productos.length === 0) {
        toast.error("Debe agregar productos al carrito antes de realizar la venta.");
        return;
      }

      const datosVenta = {
        ...data,
        productos,
        id_usuario: usuario.id_usuario,
        id_sucursal: idSucursalSeleccionada,
        total: data.total.replace(",", "."),
        total_con_descuento: data.total_con_descuento.replace(",", "."),
        nombreSucursal: usuario?.sucursal?.[0]?.nombreSucursal
      };

      
      await handleBuy(datosVenta);
      return;
    }

    // Venta en efectivo o transferencia
    setCargando(true);
    try {
      const datosVenta = {
        ...data,
        productos,
        total: data.total.replace(',', '.'),
        total_con_descuento: data.total_con_descuento.replace(',', '.')
      };

  const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/venta`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`
        },
        body: JSON.stringify(datosVenta),
      });

      if (!respuesta.ok) {
        const errorData = await respuesta.json();
        toast.error(errorData.detalle || errorData.message || "Error al realizar la venta.");
        return;
      }

      toast.success("Venta realizada!");
      reset();
      setProductos([]);

    } catch (error) {
      toast.error("Error inesperado al realizar la venta.");
    } finally {
      setCargando(false);
    }
  };


  //  PROTECCIÓN: si todavia no se cargo el store ni usuario, no reendreizar nada
  if (!storeCargado || !usuario || !token) {
    return <div className="__cargando_modal"></div>;
  }


  // LAYOUT FINAL

  const header = (
    <PanelVender
      control={control}
      register={register}
      vendedor={usuario?.nombre}
      esSuperAdmin={esSuperAdmin}
      onSeleccionarSucursal={setIdSucursalSeleccionada}
      setValue={setValue}

    />
  );

  const navigation = <Pestanias />;

  const main = (
    <div className="__cuerpo_vender">
      {cargando && <div className='__cargando_fondo'><div className="__cargando"></div></div>}

      <div className="__tabla_vender">
        <TablaConPaginacion
          columnas={columnas}
          datos={productos}
          itemsPorPagina={6}
          onElementoSeleccionado={setSeleccionado}
        />
      </div>

      <div className="__agregar_quitar">
        <Boton icono={agregar_carrito} habilitado onClick={() => setModalAgregarProducto(true)} title="Agregar producto/combo al carrito" />
        <div className="__quitar">
          <Boton icono={quitar_carrito} habilitado={seleccionado} onClick={quitarProducto} title="Quitar producto/combo del carrito"  />
        </div>
      </div>
    </div>
  );

  const footer = (
    <div className="__footer_vender">
      <form onSubmit={handleSubmit(onSubmit)}>

        <div style={{ display: "flex", marginLeft: "50px", gap: "50px", color: "white" }}>
          {permisoAgregarDescGeneral && <Tarjeta descripcion="Descuento General" forid="descuento_gral">
            <Input tipo="porcentaje" id="descuento_gral"
              {...register("descuento_gral", {
                required: "Ingrese porcentaje del descuento",
                validate: v => (v >= 0 && v <= 100) || "Debe estar entre 0 y 100"
              })}
            />
          </Tarjeta>}

          <Tarjeta descripcion="Total sin Descuento" forid="total">
            <Input tipo="costo" id="total" {...register("total")} readOnly />
          </Tarjeta>
        </div>

        <div style={{ display: "flex", marginRight: "50px", gap: "50px", color: "white" }}>
          <Tarjeta descripcion="TOTAL" forid="total_con_descuento">
            <Input tipo="costo" id="total_con_descuento" readOnly {...register("total_con_descuento")} />
          </Tarjeta>

          <Boton descripcion="VENDER" habilitado submit />
        </div>
      </form>


      <Modal visible={modalAgregarProducto} titulo="Agregar al Carrito" anchura="600px"
        funcion={() => setModalAgregarProducto(false)}
      >
        <AgregarProductoCarrito
          onGuardar={() => setModalAgregarProducto(false)}
          onAgregarProducto={manejarAgregarProducto}
          token={token}
          id_sucursal={idSucursalSeleccionada}
        />
      </Modal>
    </div>
  );

  return (
    <PlantillaPages
      header={header}
      navigation={navigation}
      main={main}
      footer={footer}
      nombreUsuario={usuario?.nombre}
      apellidoUsuario={usuario?.apellido}
      sucursal={usuario?.sucursal?.[0]?.nombreSucursal}
      id_sucursal={idSucursalSeleccionada}
      rol={usuario?.rol?.[0]?.nombreRol}
      esSuperAdmin={esSuperAdmin}
      token={token}
    />
  );
}
