import Selector from '../../Selector/Selector';
import './PanelVender.css'
import Input from "../../Input/Input";
import Tarjeta from '../../ComponentesFormulario/Tarjeta/Tarjeta';
import BotonPerfil from '../../BotonPerfil/BotonPerfil';
import { XyzTransition } from "@animxyz/react";
import { useState, useEffect } from 'react';
import { useFuncionesPerfil } from '../../../hooks/useFuncionesPerfil';
import { useWatch } from 'react-hook-form';
import leyseca from '../../../assets/leysecalogo.png'


export default function PanelVender({ control, register, vendedor, setValue, esSuperAdmin, onSeleccionarSucursal }) {



    /////////CAPTURAR LOS VALORES DEL FORMULARIO DINAMICAMENTE
    const filtro = useWatch({ control });


    //////////// BUSCA SUCURSALES EN EL BACKEND
    const [sucursales, setSucursales] = useState([]);




    useEffect(() => {
        const obtenerSucursales = async () => {
            try {
                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/sucursal`);
                const datos = await respuesta.json();

                setSucursales(datos);

                // 👉 Si hay al menos una sucursal, establecerla como valor por defecto
                if (datos.length > 0) {
                    setValue("id_sucursal", datos[0].id_sucursal);
                  
                }
            } catch (error) {
                console.log(error);
            }
        };

        obtenerSucursales();
    }, [setValue, esSuperAdmin]);

    ///USE EFECTE PPARA DEVOLVER AL COMPONENTE PADRE EL VALOR DE LA SUCURSAL
    useEffect(() => {
        if (esSuperAdmin && filtro?.id_sucursal && filtro.id_sucursal !== '') {
            onSeleccionarSucursal(filtro.id_sucursal);
        }
    }, [filtro?.id_sucursal, esSuperAdmin, onSeleccionarSucursal]);

    //TOTAL DE VENTAS
    const [totalVentas, setTotalVentas] = useState(0);

    useEffect(() => {
        const obtenerTotalVentas = async () => {
            try {
                const respuesta = await fetch(`${import.meta.env.VITE_API_BASE_URL}/api/venta/cantidadTotalVentas`);
                const total = await respuesta.json();
                setTotalVentas(total);
            } catch (error) {
                console.log('Error al obtener el total de ventas:', error);
            }
        };

        obtenerTotalVentas();
    }, []);


    ///LAYOUT
    return (
        <>
            <div className='__panel_vender'>
                <div className='__logo_background'>
                    <img src={leyseca} alt="Ley Seca Logo" />
                </div>
                <form>
                    <div className='__columna1'>
                        <div className='__col1'>
                            <Tarjeta descripcion="Fecha" forid="fecha">
                                <Input tipo="text" placeholder={new Date().toLocaleDateString()} id="fecha" readOnly />
                            </Tarjeta>
                            <Tarjeta descripcion="Vendedor" forid="vendedor">
                                <Input tipo="text" placeholder={vendedor} id="vendedor"
                                    readOnly
                                />
                            </Tarjeta>
                        </div>
                        {esSuperAdmin ? (<div className='__col1'>
                            <Tarjeta descripcion="Sucursal" forid="sucursal" >
                                <Selector
                                    id="sucursal"
                                    opciones={sucursales.map(suc => ({ label: suc.nombre, value: suc.id_sucursal }))}
                                    {...register("id_sucursal", { required: { value: true, message: "Ingrese Sucursal" } })}
                                    opcionDefecto
                                />
                            </Tarjeta>
                            <Tarjeta descripcion="Metodo de Pago" forid="metodo_pago">
                                <Selector opciones={[{ label: "Efectivo", value: "Efectivo" }, { label: "Transferencia", value: "Transferencia" },
                                 { label: "Tarjeta Debito", value: "Tarjeta Debito" }, { label: "Tarjeta Credito", value: "Tarjeta Credito" }]}
                                    id="metodo_pago"
                                    opcionDefecto
                                    {...register("metodo_pago")}
                                />
                            </Tarjeta>
                        </div>)
                            :
                            (<div className='__col2'>
                                <Tarjeta descripcion="Metodo de Pago" forid="metodo_pago">
                                    <Selector opciones={[{ label: "Efectivo", value: "Efectivo" }, { label: "Transferencia", value: "Transferencia" }]}
                                        id="metodo_pago"
                                        opcionDefecto
                                        {...register("metodo_pago")}
                                    />
                                </Tarjeta>
                            </div>)}

                    </div>
                    <div className='__columna2'>
                        <div className='__col1'>
                            <Tarjeta descripcion="Venta Nº" forid="venta">
                                <Input tipo="text" placeholder={`${totalVentas + 1}`} id="venta" readOnly />
                            </Tarjeta>
                        </div>
                    </div>
                </form>

            </div>

        </>

    )


}